"""Small XM 1.04 sequencer. Pitch names use scientific pitches (C4 = 261.6 Hz).
Score time in sixteenth rows. No instrument envelopes, plugins or sample mapping.
"""
from dataclasses import dataclass
import re, math, struct
import numpy as np

PITCH={'C':0,'D':2,'E':4,'F':5,'G':7,'A':9,'B':11}
def pitch(x):
    if isinstance(x,(int,np.integer)): return int(x)
    m=re.fullmatch(r'([A-G])([#b]?)(-?\d+)',x)
    if not m: raise ValueError(x)
    return (int(m[3])+1)*12+PITCH[m[1]]+{'':0,'#':1,'b':-1}[m[2]]
def pname(x): return ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'][x%12]+str(x//12-1)

@dataclass
class Event:
    t:int; ch:int; note:int; ins:int; vol:int; gate:object
    glide:int=0; delay:int=0; fx:object=None; pan:object=None
    vib:int=0; vib_at:int=3; release:int=0; tailfx:object=None

class Score:
    def __init__(self, bars, channels=14, speed=6, bpm=150):
        self.bars=bars;self.rows=bars*16;self.nch=channels
        self.speed=speed;self.bpm=bpm
        self.notes=[{} for _ in range(channels)]; self.extras=[]
    def note(self,t,ch,nt,ins,vol,gate=None,**kw):
        assert int(t)==t and 0<=t<self.rows,(t,ch,nt)
        assert 1<=pitch(nt)-11<=96,(nt,t)
        if t in self.notes[ch]: raise ValueError(f'Overlap ch {ch} row {t}: {self.notes[ch][t]}, {nt}')
        assert 1<=vol<=64 and (gate is None or gate>0), (nt,vol,gate)
        self.notes[ch][t]=Event(int(t),ch,pitch(nt),ins,int(vol),gate,**kw)
    def fx(self,t,ch,fx,param,vol=None):
        self.extras.append((t,ch,fx,param,vol))
    def cells(self,gains=None):
        a=np.zeros((self.rows,self.nch,5),dtype=np.uint8)
        for ch,events in enumerate(self.notes):
            gain=gains.get(ch,1.) if gains is not None else 1.
            if gain<=0: continue
            ev=[events[k] for k in sorted(events)]
            for i,e in enumerate(ev):
                t=e.t;nx=ev[i+1] if i+1<len(ev) else None
                end=nx.t if nx is not None else self.rows
                step=end-t
                limit=end if nx is None or nx.glide else min(end,t+(e.gate if e.gate is not None else step))
                dur=limit-t
                # When a target note is tied, retain the sample voice and set its new period.
                vol=min(64,max(1,round(e.vol*gain)))
                a[t,ch,:3]=[e.note-11,0 if e.glide else e.ins,vol+16]
                def fxat(r,cmd,val):
                    assert 0<=r<self.rows and type(r) in [int,np.int64,np.int32],r
                    a[r,ch,3:]=[cmd,val]
                if e.pan is not None: fxat(t,8,e.pan)
                if e.delay: fxat(t,0xE,0xD0+e.delay)
                if e.fx is not None: fxat(t,*e.fx)
                if e.glide:
                    assert i>0 and ev[i-1].ins==e.ins,(t,e)
                    fxat(t,3,e.glide)
                    ticks=abs(e.note-ev[i-1].note)*64/(4*e.glide)
                    for j in range(1,min(math.ceil(ticks/(self.speed-1)),math.ceil(dur))): fxat(t+j,3,e.glide)
                if e.vib:
                    # Regular tail vibrato on a held key, not a continuously running LFO on every note.
                    for j in range(e.vib_at,math.ceil(dur)):
                        if not any(a[t+j,ch,3:]): fxat(t+j,4,e.vib)
                if e.release and not (nx and nx.glide):
                    # One or two rows of actual tracker volume slide lead into key-up.
                    n=min(int(dur)-1,e.release)
                    if n>0:
                        v=max(1,min(15,round(.78*vol/(n*(self.speed-1)))))
                        for j in range(int(dur)-n,int(dur)):
                            if j>0: fxat(t+j,0xA,v)
                if e.tailfx is not None:
                    # (offset, command, param), explicitly placed ornaments.
                    for offset,cmd,param in e.tailfx:
                        if offset<dur: fxat(t+offset,cmd,param)
                # Natural one-shots are allowed to ring. Integer and fractional gates
                # for sustained sounds are real note-offs and tick note-cuts.
                raw=t+(e.gate if e.gate is not None else step)
                if e.gate is not None and raw < end-1e-5 and not (nx and nx.glide):
                    fl=math.floor(raw); tick=round((raw-fl)*self.speed)
                    if tick>=self.speed: fl+=1;tick=0
                    if tick==0:
                        if fl<end and fl<self.rows and fl>t: a[fl,ch,0]=97
                    elif fl<end and fl<self.rows:
                        if fl>t or not any(a[t,ch,3:]): fxat(fl,0xE,0xC0+tick)
                        elif fl+1<end: a[fl+1,ch,0]=97
        for t,ch,f,p,v in self.extras:
            if gains is not None and gains.get(ch,1.)==0:continue
            a[t,ch,3:]=[f,p]
            if v is not None:a[t,ch,2]=v
        return a

def field(s,n): return s.encode('ascii')[:n].ljust(n,b'\0')

def write_xm(path,score,patches,title='Pocket Orrery',gains=None,patlen=64):
    cells=score.cells(gains); assert len(cells)%patlen==0
    # Deduplicate identical pattern bytes into the order list, keeping the file editable.
    patterns=[]; indices={};order=[]
    for start in range(0,len(cells),patlen):
        buf=bytearray()
        for k in cells[start:start+patlen].reshape(-1,5).tolist():
            if all(k): buf.extend(k)
            else:
                mask=sum((bool(v)<<j) for j,v in enumerate(k));buf.append(128|mask)
                buf.extend(v for v in k if v)
        p=bytes(buf)
        if p not in indices:
            indices[p]=len(patterns);patterns.append(p)
        order.append(indices[p])
    data=bytearray(b'Extended Module: '+field(title,20)+b'\x1a'+field('FastTracker v2.00',20))
    data+=struct.pack('<HI8H',0x0104,276,len(order),0,score.nch,len(patterns),len(patches),1,score.speed,score.bpm)
    data+=bytes(order).ljust(256,b'\0')
    for p in patterns:
        data+=struct.pack('<IBHH',9,0,patlen,len(p))+p
    for ins in patches:
        hdr=struct.pack('<I22sBHI',263,field(ins.name,22),0,1,40).ljust(263,b'\0')
        data+=hdr
        b=ins.pcm.dtype.itemsize
        ls,ll=ins.loop
        flags=(16 if b==2 else 0)|(1 if ll else 0)
        data+=struct.pack('<IIIBbBBbB22s',len(ins.pcm)*b,ls*b,ll*b,ins.volume,ins.fine,flags,ins.pan,ins.rel,0,field(ins.wavename,22))
        vals=ins.pcm.astype(np.int32)
        data+=np.diff(vals,prepend=0).astype('<i2' if b==2 else 'i1').tobytes()
    with open(path,'wb') as f:f.write(data)
    return len(data)
