    # Deduplicate identical pattern bytes into the order list, keeping the file editable.
    patterns=[]; indices={};order=[]
    for start in range(0,len(cells),patlen):
        buf=bytearray()
        for k in cells[start:start+patlen].reshape(-1,5).tolist():
            if all(k): buf.extend(k)
            else:
                mask=sum((bool(v)<<j) for j,v in enumerate(k));buf.append(128|mask)
                buf.extend(v for v in k if v)
        p=bytes(buf)
        if p not in indices:
            indices[p]=len(patterns);patterns.append(p)
        order.append(indices[p])
    data=bytearray(b'Extended Module: '+field(title,20)+b'\x1a'+field('FastTracker v2.00',20))
    data+=struct.pack('<HI8H',0x0104,276,len(order),0,score.nch,len(patterns),len(patches),1,score.speed,score.bpm)
    data+=bytes(order).ljust(256,b'\0')
    for p in patterns:
        data+=struct.pack('<IBHH',9,0,patlen,len(p))+p
    for ins in patches:
        hdr=struct.pack('<I22sBHI',263,field(ins.name,22),0,1,40).ljust(263,b'\0')
        data+=hdr
        b=ins.pcm.dtype.itemsize
        ls,ll=ins.loop
        flags=(16 if b==2 else 0)|(1 if ll else 0)
        data+=struct.pack('<IIIBbBBbB22s',len(ins.pcm)*b,ls*b,ll*b,ins.volume,ins.fine,flags,ins.pan,ins.rel,0,field(ins.wavename,22))
        vals=ins.pcm.astype(np.int32)
        data+=np.diff(vals,prepend=0).astype('<i2' if b==2 else 'i1').tobytes()
    with open(path,'wb') as f:f.write(data)
    return len(data)
