# ---------------------------------------------------------------------------
# Drum machine. Offbeat foil, a slightly late back hand, and dry gated kicks.
# Ghost notes actually differ in pitch/gain/time; the fills are played notes,
# not a sampled break. Eight-bar cycles with specific turnarounds.
# ---------------------------------------------------------------------------

def kickseq(b,arr,root='C4'):
    for entry in arr:
        r,v,*extra=entry
        put(b,r,BD,extra[0] if extra else root,KICK,v,delay=extra[1] if len(extra)>1 else 0)

def sn(b,r,v,n='C4',late=0,roll=0):
    put(b,r,SD,n,SNARE,v,delay=late,fx=(0xE,0x90+roll) if roll else None)

def hatnote(b,r,v, *, opened=False, note='C4', late=0, ratchet=0, gate=None,pan=None):
    put(b,r,HH,note,OPEN if opened else HAT,v,gate,delay=late,pan=pan,fx=(0xE,0x90+ratchet) if ratchet else None)

def tick(b,r,v,n='C4',late=0,pan=None):put(b,r,WOOD,n,PAWL,v,delay=late,pan=pan)
def tom(b,r,n,v,gate=None,pan=None):put(b,r,SPARK,n,TOM,v,gate,pan=pan)
def clap(b,r,v,late=1,n='C4'):put(b,r,SPARK,n,CLAP,v,delay=late)
def dust(b,r,v,n='C4',pan=None):put(b,r,AIR,n,DUST,v,pan=pan)
