from meter import *
import glob,os

def kwt(f):
    # ITU-R BS.1770 analogue prototypes sampled on FFT bins.
    s=1j*f; w=1681.97445; q=.7071752
    shelf=((s*s*1.58486+s*w*1.25889/q+w*w)/(s*s+s*w/q+w*w))
    w=38.13547;q=.500327
    hp=s*s/(s*s+s*w/q+w*w)
    return np.abs(shelf*hp)**2

def w_loud(x,sr):
    sz=4096;hop=sz//2
    block=np.lib.stride_tricks.sliding_window_view(x,sz,axis=0)[::hop]
    win=np.hanning(sz);z=(np.abs(np.fft.rfft(block*win,axis=2))**2).sum(axis=1);f=np.fft.rfftfreq(sz,1/sr)
    pow=2.*np.sum(z*kwt(f),axis=1)/sz/np.sum(win*win)
    return np.round(-.691+10*np.log10(max(1.e-14,np.mean(pow))),1)

def table(first='first'):
    sections=[(0,4),(4,12),(12,20),(20,28),(28,32),(32,36),(36,40),(40,48),(48,52)]
    print('         0-4   4-12 12-20 20-28 28-32 32-36 36-40 40-48 48-52 (LUFS ungated);  energy <80 150 300 600 1200 2400 4800 9600 20k')
    for p in [f'renders/{first}.wav']+sorted(glob.glob('renders/s_*.wav')):
        sr,x=read(p);bar=round(sr*1.6);ws=[]
        for a,b in sections:ws.append(w_loud(x[a*bar:b*bar],sr))
        print(f'{os.path.basename(p).split(".")[0]:9}', ' '.join(f'{v:5.1f}' for v in ws),str(bands(x,sr)))
if __name__=='__main__':table(*(sys.argv[1:]))
